import java.util.Scanner;

public class BookFair {
    // Instance variables
    private String bname;
    private double price;
    private double discount;
    private double netPrice;

    // Default Constructor
    public BookFair() {
        bname = "";
        price = 0.0;
        discount = 0.0;
        netPrice = 0.0;
    }

    // Input method
    public void input() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Book Title: ");
        bname = sc.nextLine();
        System.out.print("Enter Book Catalog Price (Rs.): ");
        price = sc.nextDouble();
    }

    // Calculate discount and net payable amount
    public void calculate() {
        double rate;
        if (price <= 1000) {
            rate = 0.02;
        } else if (price <= 3000) {
            rate = 0.10;
        } else {
            rate = 0.15;
        }
        discount = price * rate;
        netPrice = price - discount;
    }

    // Display invoice
    public void display() {
        System.out.println("\n========================================");
        System.out.println("           BOOK FAIR RECEIPT            ");
        System.out.println("========================================");
        System.out.println("Book Title     : " + bname);
        System.out.printf("Catalog Price  : Rs. %.2f\n", price);
        System.out.printf("Discount Amount: Rs. %.2f\n", discount);
        System.out.printf("Net Amount Due : Rs. %.2f\n", netPrice);
        System.out.println("========================================");
    }

    // Main method
    public static void main(String[] args) {
        BookFair book = new BookFair();
        book.input();
        book.calculate();
        book.display();
    }
}
```

