import java.util.Scanner;

public class SelectionSortDescending {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = 15;
        int[] arr = new int[n];

        System.out.println("Enter 15 integers:");
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        System.out.print("Original Array: ");
        printArray(arr);

        // Selection Sort Algorithm (Descending Order)
        for (int i = 0; i < n - 1; i++) {
            int maxIndex = i;
            for (int j = i + 1; j < n; j++) {
                if (arr[j] > arr[maxIndex]) {
                    maxIndex = j;
                }
            }
            // Swap maximum element with element at index i
            if (maxIndex != i) {
                int temp = arr[i];
                arr[i] = arr[maxIndex];
                arr[maxIndex] = temp;
            }
        }

        System.out.print("Sorted Array (Descending Order): ");
        printArray(arr);

        sc.close();
    }

    private static void printArray(int[] arr) {
        for (int val : arr) {
            System.out.print(val + " ");
        }
        System.out.println();
    }
}
```

