import java.util.Scanner;

public class SentenceVowelTitleCase {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        String input = sc.nextLine().trim();

        if (input.isEmpty()) {
            System.out.println("Empty input.");
            return;
        }

        String[] words = input.split("\\s+");
        int vowelStartCount = 0;
        StringBuilder titleCaseSentence = new StringBuilder();

        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            if (word.length() > 0) {
                // 1. Check if first letter is a vowel
                char firstChar = Character.toUpperCase(word.charAt(0));
                if (firstChar == 'A' || firstChar == 'E' || firstChar == 'I' || 
                    firstChar == 'O' || firstChar == 'U') {
                    vowelStartCount++;
                }

                // 2. Convert to Title Case
                String titleWord = Character.toUpperCase(word.charAt(0)) + 
                                   word.substring(1).toLowerCase();
                titleCaseSentence.append(titleWord);
                if (i < words.length - 1) {
                    titleCaseSentence.append(" ");
                }
            }
        }

        System.out.println("\n--- Analysis Report ---");
        System.out.println("Words starting with a vowel: " + vowelStartCount);
        System.out.println("Title Case Sentence        : " + titleCaseSentence.toString());

        sc.close();
    }
}
```

