import java.util.Scanner;

public class TechNumberCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter an integer to check for Tech Number: ");
        int num = sc.nextInt();

        if (num <= 0) {
            System.out.println("Please enter a positive integer.");
            return;
        }

        // Count number of digits
        int temp = num;
        int digitCount = 0;
        while (temp > 0) {
            digitCount++;
            temp /= 10;
        }

        // Check if digit count is even
        if (digitCount % 2 != 0) {
            System.out.println(num + " has an odd number of digits (" + digitCount + "). Cannot be a Tech Number.");
            return;
        }

        // Split into two equal halves
        int halfDigits = digitCount / 2;
        int divisor = (int) Math.pow(10, halfDigits);

        int firstHalf = num / divisor;
        int secondHalf = num % divisor;
        int sum = firstHalf + secondHalf;
        int squareOfSum = sum * sum;

        System.out.println("First Half  : " + firstHalf);
        System.out.println("Second Half : " + secondHalf);
        System.out.println("Sum of Halves: " + sum);
        System.out.println("Square of Sum: " + squareOfSum);

        if (squareOfSum == num) {
            System.out.println(num + " is a TECH NUMBER.");
        } else {
            System.out.println(num + " is NOT a Tech Number.");
        }

        sc.close();
    }
}
```

