import java.util.Scanner;

public class MatrixBoundaryElements {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = 4;
        int[][] mat = new int[n][n];

        System.out.println("Enter 16 integers for a 4x4 matrix:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = sc.nextInt();
            }
        }

        // 1. Display Original Matrix
        System.out.println("\n--- Original Matrix ---");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.print(mat[i][j] + "\t");
            }
            System.out.println();
        }

        // 2. Display Boundary Elements and Calculate Sum
        int boundarySum = 0;
        System.out.println("\n--- Boundary Elements ---");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Boundary condition: first/last row or first/last column
                if (i == 0 || i == n - 1 || j == 0 || j == n - 1) {
                    System.out.print(mat[i][j] + "\t");
                    boundarySum += mat[i][j];
                } else {
                    System.out.print(" \t"); // Blank for inner elements
                }
            }
            System.out.println();
        }

        System.out.println("\nSum of Boundary Elements = " + boundarySum);
        sc.close();
    }
}
```

