public class PolygonOverload {
    // Method 1: Square of side n with character ch
    public void polygon(int n, char ch) {
        System.out.println("Square pattern (" + n + "x" + n + "):");
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                System.out.print(ch + " ");
            }
            System.out.println();
        }
    }

    // Method 2: Rectangle of x rows and y columns with '@'
    public void polygon(int x, int y) {
        System.out.println("Rectangle pattern (" + x + "x" + y + "):");
        for (int i = 1; i <= x; i++) {
            for (int j = 1; j <= y; j++) {
                System.out.print("@ ");
            }
            System.out.println();
        }
    }

    // Method 3: Triangle pattern of '*'
    public void polygon() {
        System.out.println("Triangle pattern:");
        for (int i = 1; i <= 4; i++) {
            for (int j = 1; j <= i; j++) {
                System.out.print("* ");
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        PolygonOverload poly = new PolygonOverload();

        System.out.println("--- Call 1: polygon(4, '$') ---");
        poly.polygon(4, '$');

        System.out.println("\n--- Call 2: polygon(3, 6) ---");
        poly.polygon(3, 6);

        System.out.println("\n--- Call 3: polygon() ---");
        poly.polygon();
    }
}
```

